package android.view;import android.os.*;import android.graphics.drawable.Drawable;public class View {public static final int VISIBLE=0,INVISIBLE=4,GONE=8;public ViewParent parent;public ViewParent getParent(){return parent;}public int visibility=0,width=100,height=100;public boolean layoutRequested;public Object token=new Object();private ViewTreeObserver observer=new ViewTreeObserver();private Handler handler=new Handler();public int getVisibility(){return visibility;}public void setVisibility(int v){visibility=v;}public Object getWindowToken(){return token;}public boolean isShown(){return visibility==0&&token!=null;}public int getWidth(){return width;}public int getHeight(){return height;}public boolean isLayoutRequested(){return layoutRequested;}public ViewTreeObserver getViewTreeObserver(){return observer;}public void replaceObserver(){observer=new ViewTreeObserver();}public boolean post(Runnable r){return handler.post(r);}public boolean postDelayed(Runnable r,long ms){return handler.postDelayed(r,ms);}public boolean removeCallbacks(Runnable r){handler.removeCallbacks(r);return true;}public void invalidate(){postInvalidateOnAnimation();}public void postInvalidateOnAnimation(){handler.postDelayed(()->observer.draw(),1);}public void setBackgroundDrawable(Drawable d){}}